{"explanation":"At each peg of a Galton board, a ball bounces left or right with probability ½ (or p, if you tilt it with the slider). After n rows, the bin it lands in is just the number of right-bounces k. There are C(n,k) different paths that end in bin k, so the probability of landing there is C(n,k)·pᵏ(1−p)ⁿ⁻ᵏ, which is the binomial distribution. The blue histogram shows the share of balls in each bin. As more balls drop, it settles onto the red theoretical binomial curve (law of large numbers). With many rows, that curve looks like a bell curve.","manimCode":"const n = 8;
const dx = 0.5;
const dy = 0.38;
const topY = 3.0;
const floorY = -3.4;
const H = 2.9;
let p = 0.5;

// ---- Pegs ----
for (let r = 0; r < n; r++) {
  for (let j = 0; j <= r; j++) {
    const peg = new Dot({ point: [(j - r / 2) * dx, topY - r * dy, 0], color: GRAY, radius: 0.05 });
    scene.add(peg);
  }
}

// ---- Bin walls and floor ----
for (let k = 0; k <= n + 1; k++) {
  const x = (k - n / 2 - 0.5) * dx;
  scene.add(new Line({ start: [x, floorY, 0], end: [x, -0.35, 0], color: GRAY_B || GRAY, strokeWidth: 2 }));
}
scene.add(new Line({ start: [(-n / 2 - 0.5) * dx, floorY, 0], end: [(n / 2 + 0.5) * dx, floorY, 0], color: WHITE, strokeWidth: 3 }));

// ---- Histogram bars ----
const counts = new Array(n + 1).fill(0);
let total = 0;
const bars = [];
function barVerts(k, h) {
  const x = (k - n / 2) * dx;
  const w = dx * 0.4;
  const hh = Math.max(h, 0.001);
  return [[x - w, floorY, 0], [x + w, floorY, 0], [x + w, floorY + hh, 0], [x - w, floorY + hh, 0]];
}
for (let k = 0; k <= n; k++) {
  const b = new Polygon({ vertices: barVerts(k, 0), color: BLUE });
  b.setFill(BLUE, 0.55);
  b.setStrokeWidth(1);
  bars.push(b);
  scene.add(b);
}

// ---- Binomial theory ----
function binom(nn, k) { let c = 1; for (let i = 1; i <= k; i++) c = c * (nn - k + i) / i; return c; }
function probs() { const a = []; for (let k = 0; k <= n; k++) a.push(binom(n, k) * Math.pow(p, k) * Math.pow(1 - p, n - k)); return a; }
let P = probs();
let maxP = Math.max(...P);
let theoryMobs = [];
function buildTheory() {
  theoryMobs.forEach(m => scene.remove(m));
  theoryMobs = [];
  P = probs();
  maxP = Math.max(...P);
  const pts = P.map((pk, k) => [(k - n / 2) * dx, floorY + pk / maxP * H, 0]);
  for (let k = 0; k < n; k++) {
    theoryMobs.push(new Line({ start: pts[k], end: pts[k + 1], color: RED, strokeWidth: 3 }));
  }
  pts.forEach(pt => theoryMobs.push(new Dot({ point: pt, color: RED, radius: 0.06 })));
  theoryMobs.forEach(m => scene.add(m));
}
buildTheory();

function updateBars() {
  for (let k = 0; k <= n; k++) {
    const frac = total > 0 ? counts[k] / total : 0;
    const h = Math.min(frac / maxP * H, H + 0.4);
    bars[k].setVertices(barVerts(k, h));
  }
}

// ---- Labels ----
const formula = new MathTex({ latex: 'P(k)=\\binom{n}{k}p^k(1-p)^{n-k}', color: WHITE });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([-4.6, 2.6, 0]);
scene.add(formula);

const legend1 = new Text({ text: 'Blue: observed fraction', color: BLUE, fontSize: 20 });
legend1.moveTo([-4.6, 1.7, 0]);
const legend2 = new Text({ text: 'Red: binomial (n = 8)', color: RED, fontSize: 20 });
legend2.moveTo([-4.6, 1.3, 0]);
scene.add(legend1, legend2);

let counterText = new Text({ text: 'Balls: 0', color: YELLOW, fontSize: 26 });
counterText.moveTo([-4.6, 0.6, 0]);
scene.add(counterText);
let shownTotal = -1;
function refreshCounter() {
  if (shownTotal === total) return;
  shownTotal = total;
  scene.remove(counterText);
  counterText = new Text({ text: 'Balls: ' + total, color: YELLOW, fontSize: 26 });
  counterText.moveTo([-4.6, 0.6, 0]);
  scene.add(counterText);
}

// bin labels k
for (let k = 0; k <= n; k++) {
  const t = new Text({ text: String(k), color: GRAY, fontSize: 18 });
  t.moveTo([(k - n / 2) * dx, floorY - 0.25, 0]);
  scene.add(t);
}

// ---- Ball simulation ----
const balls = [];
const segT = 0.11;
const fallT = 0.35;
function spawnBall() {
  if (balls.length > 45) return;
  const pts = [[0, topY + 0.5, 0]];
  let k = 0;
  for (let r = 0; r < n; r++) {
    pts.push([(k - r / 2) * dx, topY - r * dy + 0.11, 0]);
    if (Math.random() < p) k++;
  }
  const bx = (k - n / 2) * dx;
  pts.push([bx, topY - n * dy + 0.11, 0]);
  pts.push([bx, floorY + 0.1, 0]);
  const dot = new Dot({ point: pts[0], color: YELLOW, radius: 0.07 });
  scene.add(dot);
  balls.push({ dot, pts, k, start: performance.now() / 1000 });
}

function ballPos(b, t) {
  const nPeg = b.pts.length - 2; // segments before final fall
  let idx = Math.floor(t / segT);
  if (idx < nPeg) {
    const s = t / segT - idx;
    const a = b.pts[idx], c = b.pts[idx + 1];
    const arc = idx > 0 ? 0.12 * Math.sin(Math.PI * s) : 0;
    return [a[0] + (c[0] - a[0]) * s, a[1] + (c[1] - a[1]) * s + arc, 0];
  }
  const s = Math.min((t - nPeg * segT) / fallT, 1);
  const a = b.pts[nPeg], c = b.pts[nPeg + 1];
  const e = s * s;
  return [a[0], a[1] + (c[1] - a[1]) * e, 0];
}
const lifeT = (n + 1) * segT + fallT;

let autoDrop = true;
let lastSpawn = 0;
let lastCounter = 0;
const ticker = new Dot({ point: [0, 0, 0], radius: 0.001 });
ticker.setOpacity(0);
scene.add(ticker);
ticker.addUpdater(() => {
  const now = performance.now() / 1000;
  if (autoDrop && now - lastSpawn > 0.09) { spawnBall(); lastSpawn = now; }
  for (let i = balls.length - 1; i >= 0; i--) {
    const b = balls[i];
    const t = now - b.start;
    if (t >= lifeT) {
      scene.remove(b.dot);
      balls.splice(i, 1);
      counts[b.k]++;
      total++;
      updateBars();
    } else {
      b.dot.moveTo(ballPos(b, t));
    }
  }
  if (now - lastCounter > 0.25) { refreshCounter(); lastCounter = now; }
});

function resetAll() {
  balls.forEach(b => scene.remove(b.dot));
  balls.length = 0;
  for (let k = 0; k <= n; k++) counts[k] = 0;
  total = 0;
  updateBars();
  refreshCounter();
}

// ---- Controls ----
const controls = new Controls(scene, { position: 'top-right' });
controls.addCheckbox({ label: 'Auto drop', checked: true, onChange: (c) => { autoDrop = c; } });
controls.addButton({ label: 'Drop 1 ball', onClick: () => spawnBall() });
controls.addButton({ label: 'Drop 30 balls', onClick: () => {
  let i = 0;
  const id = setInterval(() => { spawnBall(); i++; if (i >= 30) clearInterval(id); }, 70);
}});
controls.addSlider({ label: 'p (right bounce)', min: 0.1, max: 0.9, value: 0.5, step: 0.05, onChange: (v) => {
  p = v;
  buildTheory();
  resetAll();
}});
controls.addButton({ label: 'Reset', onClick: () => resetAll() });

await scene.wait(999999);"}

